def is_scalar_field(field: Field) -> bool:
    if not (
        field.shape == Shape.SINGLETON
        and not lenient_issubclass(field.type_, BaseModel)
        and not lenient_issubclass(field.type_, sequence_types + (dict,))
        and not isinstance(field.schema, params.Body)
    ):
        return False
    if field.sub_fields:
        for sub_field in field.sub_fields:
            if not (
                sub_field.shape == Shape.SINGLETON
                and not lenient_issubclass(sub_field.type_, BaseModel)
                and not lenient_issubclass(sub_field.type_, sequence_types + (dict,))
                and not isinstance(sub_field.schema, params.Body)
            ):
                return False
    return True
