```python
def is_scalar_field(field: Field) -> bool:
    if field.shape!= Shape.SINGLETON:
        return False
    if lenient_issubclass(field.type_, BaseModel):
        return False
    if lenient_issubclass(field.type_, (list, tuple, dict)):
        return False
    if isinstance(field.schema, params.Body):
        return False
    if hasattr(field.type_, '__origin__') and field.type_.__origin__ == typing.Union:
        return all(is_scalar_field(f) for f in field.sub_fields)
    return True
```

```python
def is_scalar_field(field: Field) -> bool:
    if not (
        field.shape == Shape.SINGLETON
        and not lenient_issubclass(field.type_, BaseModel)
        and not lenient_issubclass(field.type_, sequence_types + (dict,))
        and not isinstance(field.schema, params.Body)
    ):
        return False
    if field.sub_fields:
        if not all(is_scalar_field(f) for f in field.sub_fields):
            return False
    if hasattr(field.type_, '__origin__') and field.type_.__origin__ == Union:
        return all(lenient_issubclass(t, (int, float, str, bool, None)) for t in field.type_.__args__)
    return True
```
